"""Tests for tasks_api.repository — InMemoryTaskRepository and normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make_task(self, id=1, title="Test"):
        return Task(id=id, title=title)

    def test_add_and_get(self, repo):
        task = self._make_task()
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make_task(1))

    def test_list_returns_all(self, repo):
        repo.add(self._make_task(1))
        repo.add(self._make_task(2, "Other"))
        result = list(repo.list())
        assert len(result) == 2

    def test_update_existing(self, repo):
        task = self._make_task()
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make_task(99))

    def test_delete_existing(self, repo):
        repo.add(self._make_task())
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_deduplicates(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        names = [t.name for t in result]
        assert names == ["foo", "bar"]

    def test_accepts_strings(self):
        result = normalize_tags(["Hello", "World"])
        assert [t.name for t in result] == ["hello", "world"]

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("alpha"), "ALPHA", "beta"])
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_preserves_first_seen_order(self):
        result = normalize_tags(["c", "a", "b", "A"])
        assert [t.name for t in result] == ["c", "a", "b"]
